import{_ as i,a as t,b as s,c as o,d as r,e as n,f as a}from"./chunks/git_16.DuMhbUDR.js";import{_ as l,c as u,o as p,ag as c}from"./chunks/framework.BtwP-r-R.js";const d="/14B-POO-A26/assets/git_github_1.BpLyQDrl.png",g="/14B-POO-A26/assets/git_github_2.3k7ylk36.png",m="/14B-POO-A26/assets/git_github_3.Dv_CNS54.png",F=JSON.parse('{"title":"Git avec Visual Studio et GitHub","description":"","frontmatter":{},"headers":[],"relativePath":"git_github.md","filePath":"git_github.md"}'),h={name:"git_github.md"};function f(v,e,k,q,b,_){return p(),u("div",null,[...e[0]||(e[0]=[c('<h1 id="git-avec-visual-studio-et-github" tabindex="-1">Git avec Visual Studio et GitHub <a class="header-anchor" href="#git-avec-visual-studio-et-github" aria-label="Permalink to &quot;Git avec Visual Studio et GitHub&quot;">​</a></h1><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Installez Git sans changer les options par défaut : <a href="http://git-scm.com/downloads" target="_blank" rel="noreferrer">http://git-scm.com/downloads</a></p><p><strong>Liens utiles</strong></p><ul><li>Documentation officielle de Git : <a href="https://git-scm.com/doc" target="_blank" rel="noreferrer">https://git-scm.com/doc</a></li><li>Cours rapide sur Git en 15 minutes : <a href="https://try.github.io/levels/1/challenges/1" target="_blank" rel="noreferrer">https://try.github.io/levels/1/challenges/1</a></li><li>Cours sur Git (niveau 1 gratuit) : <a href="http://gitreal.codeschool.com/levels/1" target="_blank" rel="noreferrer">http://gitreal.codeschool.com/levels/1</a></li><li>Cours sur Git et GitHub sur OpenClassRooms : <a href="https://openclassrooms.com/courses/gerer-son-code-avec-git-et-github" target="_blank" rel="noreferrer">https://openclassrooms.com/courses/gerer-son-code-avec-git-et-github</a></li></ul><h2 id="configuration-initiale-pour-une-equipe-travaillant-sur-un-meme-projet" tabindex="-1">Configuration initiale pour une équipe travaillant sur un même projet <a class="header-anchor" href="#configuration-initiale-pour-une-equipe-travaillant-sur-un-meme-projet" aria-label="Permalink to &quot;Configuration initiale pour une équipe travaillant sur un même projet&quot;">​</a></h2><ol><li><p><strong>Pour les deux coéquipiers</strong></p><ul><li>Créez-vous un compte sur le cloud GitHub.com (<a href="https://github.com/" target="_blank" rel="noreferrer">https://github.com/</a>).</li></ul></li><li><p><strong>Coéquipier 1</strong> : Celui ayant une version à jour du projet</p><ol><li>Ouvrir le projet Visual Studio existant et sélectionnier le menu <code>Git--&gt; créer un dépôt Git</code></li></ol><p><img src="'+d+'" alt="Nouveau projet github"></p><ol start="2"><li>Séctionner le modèle .gitignore par défaut de Visual Studio</li><li>Se connecter à son compte GitHub, indiquer le nom du dépôt et cocher la case &quot;Dépôt privé&quot;</li></ol><p><img src="'+g+'" alt="Nouveau projet github"></p><ol start="4"><li><p>Cliquer sur le bouton <code>Créer et envoyer (push)</code></p></li><li><p>Sur le site de GitHub, sélectionner votre projet et cliquer sur le menu <code>Settings</code>, cliquer sur l&#39;option <code>Collaborators</code>, cliquer sur le bouton <code>Add people</code> et ajouter votre coéquiper.</p></li></ol><p><img src="'+m+'" alt="Nouveau projet github"></p></li></ol><h2 id="ignorer-des-fichier-gitignore" tabindex="-1">Ignorer des fichier (.gitignore) <a class="header-anchor" href="#ignorer-des-fichier-gitignore" aria-label="Permalink to &quot;Ignorer des fichier (.gitignore)&quot;">​</a></h2><p>Pour ignorer certains fichiers de votre solution afin qu&#39;ils ne soient pas publiés sur le dépôt distant et ainsi éviter des conflits, vous devez utiliser un fichier nommé « .gitignore » . Si vous ne l&#39;avez pas fait lors de la création du dépôt, voici comment faire.</p><p>Vous devez :</p><ol><li>Cliquer sur l&#39;option « <strong>…</strong> » à partir du menu « <strong>Gérer les dépôt distants …</strong> ».</li></ol><p><img src="'+i+'" alt="Nouveau projet git la"></p><ol start="2"><li>Vous devez par la suite sélectionner dans le menu, l&#39;option <strong>Paramètres du dépôt Git -&gt; Général</strong>. Dans la section, « <strong>Git files</strong> », cliquer sur le bouton « <strong>Ajouter</strong> » vis-à-vis Ingorer le fichier:</li></ol><p><img src="'+t+'" alt="Nouveau projet git la"></p><h2 id="comment-faire-pour-conserver-des-versions-de-fichier-localement" tabindex="-1">Comment faire pour conserver des versions de fichier localement? <a class="header-anchor" href="#comment-faire-pour-conserver-des-versions-de-fichier-localement" aria-label="Permalink to &quot;Comment faire pour conserver des versions de fichier localement?&quot;">​</a></h2><ul><li>À partir l&#39;onglet &quot;Modification Git&quot; <ul><li>Indiquez le texte du &quot;<strong>Commit</strong>&quot; (Celui-ci doit être significatif).</li><li>Sélectionner les fichiers à ajouter au commit.</li><li>Cliquez sur « <strong>Valider Tout</strong> ».</li></ul></li></ul><p><img src="'+s+'" alt="Nouveau projet git la"></p><h2 id="comment-faire-pour-accepter-une-version-modifiee-de-certains-fichiers-et-les-mettre-sur-le-depot-distant" tabindex="-1">Comment faire pour accepter une version modifiée de certains fichiers et les mettre sur le dépôt distant ? <a class="header-anchor" href="#comment-faire-pour-accepter-une-version-modifiee-de-certains-fichiers-et-les-mettre-sur-le-depot-distant" aria-label="Permalink to &quot;Comment faire pour accepter une version modifiée de certains fichiers et les mettre sur le dépôt distant ?&quot;">​</a></h2><p>Important : Avant de pouvoir effectuer un « <strong>Push</strong> », vous devez avoir une copie à jour des fichiers du dépôt distant. Ainsi, il est préférable, <strong>voire nécessaire, de toujours faire un « Pull » avant un « Push »</strong>.</p><ul><li>Exécutez les commandes suivantes dans cet ordre : <ul><li>À partir de l&#39;onglet « Modification Git», saisissez le texte du &quot;Commit&quot; (celui-ci doit être significatif) et cliquez sur « <strong>Valider tout et synchroniser</strong> ».</li><li>Éventuellement, vous devrez gérer manuellement les conflits si la version locale d’un fichier est différente de celle sur le dépôt distant.</li><li>S’il n’y a aucun conflit, alors cliquez sur le lien « <strong>Pousser</strong> ».</li></ul></li></ul><h2 id="comment-resoudre-des-conflits" tabindex="-1">Comment résoudre des conflits <a class="header-anchor" href="#comment-resoudre-des-conflits" aria-label="Permalink to &quot;Comment résoudre des conflits&quot;">​</a></h2><p>Lorsque vous tentez de pousser vos modifications sur le dépôt distant, il se peut que le message suivant s&#39;affiche :</p><p><img src="'+o+'" alt="Message de conflit"></p><p>Cela indique que votre version du code n&#39;est pas à jour par rapport à celle se trouvant sur le dépôt distant. <strong>Vous devez donc synchroniser votre code en tirant celui qui se trouve sur le dépôt distant</strong>.</p><p>Lors d’une synchronisation, il se peut que vous ayez des conflits à résoudre avant de pouvoir pousser votre code :</p><p><img src="'+r+'" alt="Message de conflit"></p><p>Dans ce cas, cliquez sur le lien « <strong>Ouvrir l&#39;éditeur de fusion</strong> ». La fenêtre suivante affichera les conflits :</p><p><img src="'+n+'" alt="Message de conflit"></p><p>Vous n’aurez qu’à cocher le code du côté distant ou local que vous désirez conserver et celui-ci apparaîtra dans la section du bas. Une fois terminé, cliquez sur le bouton « <strong>Accepter la fusion</strong> ».</p><p><img src="'+a+`" alt="Message de conflit"></p><p>À partir de la fenêtre « <strong>Modifications Git</strong> », saisissez le texte du &quot;Commit&quot; (celui-ci doit être significatif) et cliquez sur « <strong>Valider les changements pousser</strong>».</p><h2 id="quand-faire-un-commit" tabindex="-1">Quand faire un commit <a class="header-anchor" href="#quand-faire-un-commit" aria-label="Permalink to &quot;Quand faire un commit&quot;">​</a></h2><ul><li><p><strong>Petites étapes significatives</strong> : Il est recommandé de faire un commit chaque fois que vous avez atteint un point stable dans votre travail, même si la fonctionnalité n&#39;est pas entièrement terminée. Par exemple, après avoir ajouté une fonction ou corrigé un bug.</p></li><li><p><strong>Unité logique de travail</strong> : Le commit doit représenter une unité logique de travail. Évitez de mélanger plusieurs modifications sans lien dans un seul commit (par exemple, éviter de corriger un bug et d&#39;ajouter une nouvelle fonctionnalité dans le même commit).</p></li><li><p><strong>Tests réussis :</strong> Faites un commit lorsque vous avez testé votre code et que tout fonctionne correctement (ou au moins fonctionne comme prévu).</p></li><li><p><strong>Messages clairs</strong> : Les messages de commit doivent être descriptifs, expliquant ce qui a été modifié et pourquoi.</p></li></ul><p>Une bonne description de commit doit comprendre deux parties :</p><ul><li>Un message de titre clair (maximum 50 caractères recommandé)</li><li>Une description plus détaillée (<strong>optionnelle</strong>) qui explique davantage le &quot;pourquoi&quot; du changement, et non seulement le &quot;quoi&quot;.</li></ul><p><strong>structure d&#39;un commit</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&gt;(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">portée facultative</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description courte</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description détaillée (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">optionnelle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Types de commits courants :</p><ul><li><strong>feat</strong> : pour une nouvelle fonctionnalité.</li><li><strong>fix</strong> : pour une correction de bug.</li><li><strong>chore</strong> : pour les changements de configuration ou maintenance qui n&#39;affectent pas le code de production (par ex., mise à jour des dépendances).</li><li><strong>docs</strong> : pour des modifications concernant la documentation.</li><li><strong>style</strong> : pour des changements de formatage ou de style de code (qui ne modifient pas le comportement du code).</li><li><strong>refactor</strong> : pour une refonte du code qui n&#39;ajoute pas de nouvelles fonctionnalités ni ne corrige de bugs.</li><li><strong>test</strong> : pour ajouter ou modifier des tests.</li><li><strong>perf</strong> : pour améliorer les performances.</li><li><strong>ci</strong> : pour des modifications liées à l&#39;intégration continue ou les outils de déploiement.</li></ul><p>Voici un exemple :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">feat(auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">): Ajout de la fonctionnalité de connexion utilisateur</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Ce</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ajoute</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> la</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fonctionnalité</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> d&#39;authentification de base, permettant aux utilisateurs de se connecter. Il inclut le formulaire de connexion, l&#39;intégration</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> de</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> l&#39;API et la gestion des erreurs.</span></span></code></pre></div><h3 id="bonne-pratiques-generales" tabindex="-1">Bonne pratiques générales <a class="header-anchor" href="#bonne-pratiques-generales" aria-label="Permalink to &quot;Bonne pratiques générales&quot;">​</a></h3><ul><li><p><strong>Utiliser l&#39;impératif présent</strong> : Les messages de commit doivent être rédigés à l’impératif, comme si vous donniez un ordre au système. Exemple : &quot;Ajout de la fonctionnalité de connexion&quot;</p></li><li><p><strong>Clarté et concision</strong> : Soyez clair sur ce que vous avez fait et pourquoi. Un bon titre de commit doit être compréhensible sans avoir besoin de consulter le code lui-même.</p></li><li><p><strong>Des messages courts pour le titre</strong> : Limitez le titre à 50 caractères pour qu&#39;il reste lisible. Utilisez la description pour des détails supplémentaires si nécessaire.</p></li><li><p><strong>Séparer les commits logiquement</strong> : Un commit doit correspondre à un seul changement logique. Ne mélangez pas plusieurs modifications sans lien dans un seul commit.</p></li></ul><h2 id="quand-faire-un-push" tabindex="-1">Quand faire un push <a class="header-anchor" href="#quand-faire-un-push" aria-label="Permalink to &quot;Quand faire un push&quot;">​</a></h2><ul><li><p><strong>Travail terminé ou stable</strong> : Faites un push lorsque vous avez atteint une étape significative, comme une fonctionnalité terminée, ou lorsque le code est stable et ne casse rien.</p></li><li><p><strong>Partager votre travail</strong> : Si vous travaillez en équipe, il est important de faire un push régulièrement pour partager vos changements avec vos coéquipiers et éviter les conflits lors des fusions.</p></li><li><p><strong>Avant de commencer une nouvelle tâche</strong> : Avant de vous lancer dans une nouvelle fonctionnalité ou correction de bug, assurez-vous de faire un push pour sauvegarder et synchroniser votre travail en cours.</p></li><li><p><strong>S&#39;assurer que les autres peuvent accéder à votre travail</strong> : Si vous devez quitter votre poste ou que vous travaillez depuis différents ordinateurs, faites un push pour sauvegarder votre code sur le dépôt distant.</p></li></ul>`,45)])])}const E=l(h,[["render",f]]);export{F as __pageData,E as default};
